const trackers = new Map();

export function initialize(dotNetRef, timeoutMs) {
    const state = {
        dotNetRef,
        timeoutMs,
        isIdle: false,
        timerId: null,
        handler: null,
    };

    const events = ["mousemove", "keydown", "click", "scroll"];

    function resetTimer() {
        clearTimeout(state.timerId);
        if (state.isIdle) {
            state.isIdle = false;
            state.dotNetRef.invokeMethodAsync("OnUserActive");
        }
        state.timerId = setTimeout(() => {
            state.isIdle = true;
            state.dotNetRef.invokeMethodAsync("OnUserIdle");
        }, state.timeoutMs);
    }

    state.handler = resetTimer;
    state.events = events;

    for (const evt of events) {
        document.addEventListener(evt, resetTimer, { passive: true });
    }

    // Start the initial timer
    state.timerId = setTimeout(() => {
        state.isIdle = true;
        state.dotNetRef.invokeMethodAsync("OnUserIdle");
    }, state.timeoutMs);

    const id = crypto.randomUUID();
    trackers.set(id, state);
    return id;
}

export function dispose(id) {
    const state = trackers.get(id);
    if (!state) return;

    clearTimeout(state.timerId);
    for (const evt of state.events) {
        document.removeEventListener(evt, state.handler);
    }
    trackers.delete(id);
}

export function updateTimeout(id, timeoutMs) {
    const state = trackers.get(id);
    if (!state) return;
    state.timeoutMs = timeoutMs;
}

